From 16da4244cc685fb626fdab6848892e11f491b37e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:17:52 +0100
Subject: [PATCH] kcm, applet: say when the Bluetooth service is not running

When bluetoothd was not running, the KCM said "No devices paired" and
the applet offered to enable Bluetooth, though neither could help. Both
now say that the Bluetooth service is not running, with no action.

BUG: 481513
---
 src/applet/qml/FullRepresentation.qml |  4 +++-
 src/kcm/ui/main.qml                   | 12 +++++++++++-
 2 files changed, 14 insertions(+), 2 deletions(-)

diff --git a/src/applet/qml/FullRepresentation.qml b/src/applet/qml/FullRepresentation.qml
index c281b129..f4e7f8cf 100644
--- a/src/applet/qml/FullRepresentation.qml
+++ b/src/applet/qml/FullRepresentation.qml
@@ -154,6 +154,8 @@ PlasmaExtras.Representation {
                         // bluetooth is disabled even when there are physical devices
                         if (BluezQt.Manager.rfkill.state === BluezQt.Rfkill.Unknown) {
                             return i18n("No Bluetooth adapters available");
+                        } else if (!BluezQt.Manager.operational) {
+                            return i18n("The Bluetooth service is not running");
                         } else if (!BluezQt.Manager.bluetoothOperational) {
                             return i18n("Bluetooth is disabled");
                         } else if (root.emptyList) {
@@ -164,7 +166,7 @@ PlasmaExtras.Representation {
                     }

                     helpfulAction: {
-                        if (BluezQt.Manager.rfkill.state === BluezQt.Rfkill.Unknown) {
+                        if (BluezQt.Manager.rfkill.state === BluezQt.Rfkill.Unknown || !BluezQt.Manager.operational) {
                             return null;
                         } else if (!BluezQt.Manager.bluetoothOperational) {
                             return toggleBluetoothAction;
diff --git a/src/kcm/ui/main.qml b/src/kcm/ui/main.qml
index 5d0da102..a2d828a2 100644
--- a/src/kcm/ui/main.qml
+++ b/src/kcm/ui/main.qml
@@ -129,6 +129,16 @@ KCMUtils.ScrollViewKCM {
             anchors.centerIn: parent
         }

+        Kirigami.PlaceholderMessage {
+            id: serviceNotRunningMessage
+            visible: !BluezQt.Manager.operational && !noBluetoothMessage.visible
+            icon.name: "network-bluetooth-inactive"
+            text: i18n("The Bluetooth service is not running")
+            explanation: i18n("Bluetooth devices cannot be used until the Bluetooth system service is started")
+            width: parent.width - (Kirigami.Units.largeSpacing * 4)
+            anchors.centerIn: parent
+        }
+
         Kirigami.PlaceholderMessage {
             id: bluetoothDisabledMessage
             visible: BluezQt.Manager.operational && !BluezQt.Manager.bluetoothOperational && !noBluetoothMessage.visible
@@ -147,7 +157,7 @@ KCMUtils.ScrollViewKCM {
         }

         Kirigami.PlaceholderMessage {
-            visible: !noBluetoothMessage.visible && !bluetoothDisabledMessage.visible && list.count === 0
+            visible: !noBluetoothMessage.visible && !serviceNotRunningMessage.visible && !bluetoothDisabledMessage.visible && list.count === 0
             icon.name: "network-bluetooth-activated"
             text: i18n("No devices paired")
             explanation: xi18nc("@info", "Click <interface>Pair Device…</interface> to pair some")
-- 
2.53.0
